def pose_matrix(position_xyz, quaternion_xyzw) -> np.ndarray:
    position = np.asarray(position_xyz, dtype=float)
    quaternion = np.asarray(quaternion_xyzw, dtype=float)
    if position.shape != (3,) or quaternion.shape != (4,):
        raise ValueError("pose has the wrong shape")
    if not np.all(np.isfinite(position)) or not np.all(np.isfinite(quaternion)):
        raise ValueError("pose contains non-finite values")
    transform = np.eye(4, dtype=float)
    transform[:3, :3] = quaternion_to_rotation(*quaternion)
    transform[:3, 3] = position
    return transform


